#include "si/GaussianParser.hpp"
#include <chrono>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <string>
namespace { std::filesystem::path syntheticGaussian(int megabytes) { const auto path=std::filesystem::temp_directory_path()/"si_generator_native_benchmark.log"; std::ofstream output(path,std::ios::binary|std::ios::trunc); output << "#p ub3lyp/def2-svp opt freq\n\n"; const std::string filler=" Population analysis placeholder 1234567890 ABCDEFGHIJKLMNOPQRSTUVWXYZ\n"; const auto target=static_cast<std::uintmax_t>(megabytes)*1024U*1024U; while(static_cast<std::uintmax_t>(output.tellp())<target) output << filler; output << "SCF Done:  E(UB3LYP) =  -150.101010     A.U.\nZero-point correction=                           0.123456 (Hartree/Particle)\nThermal correction to Energy=                    0.234567\nNormal termination of Gaussian 16\n"; return path; } }
int main(int argc,char** argv){if(argc!=2){std::cerr<<"usage: si_benchmark FILE | --synthetic-MEGABYTES\n";return 2;}const bool synthetic=std::string(argv[1]).rfind("--synthetic-",0)==0;int megabytes=0;if(synthetic){try{megabytes=std::stoi(std::string(argv[1]).substr(12));}catch(...){std::cerr<<"invalid synthetic size\n";return 2;}if(megabytes<=0){std::cerr<<"invalid synthetic size\n";return 2;}}const std::filesystem::path path=synthetic?syntheticGaussian(megabytes):std::filesystem::path(argv[1]);const auto size=std::filesystem::file_size(path);si::GaussianParser parser;auto start=std::chrono::steady_clock::now();auto cold=parser.parse(path);auto coldMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();si::GaussianCache cache;start=std::chrono::steady_clock::now();auto first=cache.get(path);auto cachePopulateMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();start=std::chrono::steady_clock::now();auto hit=cache.get(path);auto cacheHitMs=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<"file_bytes="<<size<<"\ncold_parse_ms="<<coldMs<<"\ncache_populate_ms="<<cachePopulateMs<<"\ncache_hit_ms="<<cacheHitMs<<"\ngeometry_atoms="<<cold.finalGeometry.size()<<"\nspin_atoms="<<cold.spinDensities.size()<<"\n";if(synthetic)std::filesystem::remove(path);return cold.success?0:1;}
